const html = $input.first().json.data || '';
const url = $input.first().json.$response?.request?.url || '';

const result = {
  profile_url: url,
  name: null,
  headline: null,
  location: null,
  about: null,
  current_company: null,
  current_title: null,
  profile_image: null,
  experience: [],
  education: [],
  skills: [],
  certifications: [],
  languages: [],
  raw_schema: null
};

// --- 1. Extract JSON-LD structured data (most reliable) ---
const jsonLdMatch = html.match(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/);
if (jsonLdMatch) {
  try {
    const schema = JSON.parse(jsonLdMatch[1]);
    result.raw_schema = schema;
    result.name = schema.name || null;
    result.headline = schema.jobTitle || null;
    result.current_company = schema.worksFor?.name || null;
    result.profile_image = schema.image || null;

    if (Array.isArray(schema.alumniOf)) {
      result.education = schema.alumniOf.map(edu => ({
        school: edu.name || null,
        url: edu.url || null
      }));
    }

    if (Array.isArray(schema.hasCredential)) {
      result.certifications = schema.hasCredential.map(c => ({
        name: c.name || null,
        issuer: c.recognizedBy?.name || null
      }));
    }
  } catch (e) {
    // JSON-LD parse failed, continue with HTML fallback
  }
}

// --- 2. HTML fallback: name ---
if (!result.name) {
  const nameMatch = html.match(/<title>([^|<]+)/);
  result.name = nameMatch ? nameMatch[1].trim() : null;
}

// --- 3. HTML fallback: headline ---
if (!result.headline) {
  const hlMatch = html.match(/class="[^"]*top-card-layout__headline[^"]*"[^>]*>([^<]+)</);
  result.headline = hlMatch ? hlMatch[1].trim() : null;
}

// --- 4. HTML fallback: location ---
const locMatch = html.match(/class="[^"]*top-card__subline-item[^"]*"[^>]*>([^<]+)</);
if (locMatch) result.location = locMatch[1].trim();

// --- 5. HTML fallback: about/summary ---
const aboutMatch = html.match(/class="[^"]*core-section-container__content[^"]*"[\s\S]*?<p[^>]*>([\s\S]*?)<\/p>/);
if (aboutMatch) {
  result.about = aboutMatch[1].replace(/<[^>]+>/g, '').trim();
}

// --- 6. Experience entries ---
const expSection = html.match(/id="experience"[\s\S]*?(<section[\s\S]*?<\/section>)/);
if (expSection) {
  const expItems = expSection[1].split(/<li[^>]*>/).slice(1);
  for (const item of expItems) {
    const expTitle = item.match(/class="[^"]*experience-item__title[^"]*"[^>]*>([^<]+)</);
    const expCompany = item.match(/class="[^"]*experience-item__subtitle[^"]*"[^>]*>([^<]+)</);
    const expDates = item.match(/class="[^"]*experience-item__duration[^"]*"[^>]*>([^<]+)</);
    const expLocation = item.match(/class="[^"]*experience-item__location[^"]*"[^>]*>([^<]+)</);
    const expDesc = item.match(/class="[^"]*experience-item__description[^"]*"[^>]*>([\s\S]*?)<\/p>/);

    if (expTitle || expCompany) {
      result.experience.push({
        title: expTitle ? expTitle[1].trim() : null,
        company: expCompany ? expCompany[1].trim() : null,
        duration: expDates ? expDates[1].trim() : null,
        location: expLocation ? expLocation[1].trim() : null,
        description: expDesc ? expDesc[1].replace(/<[^>]+>/g, '').trim() : null
      });
    }
  }
}

// --- 7. Skills ---
const skillMatches = html.matchAll(/class="[^"]*skill-card-component__display-name[^"]*"[^>]*>([^<]+)</);
for (const m of skillMatches) {
  result.skills.push(m[1].trim());
}

// --- 8. Languages ---
const langSection = html.match(/id="languages"[\s\S]*?(<section[\s\S]*?<\/section>)/);
if (langSection) {
  const langMatches = langSection[1].matchAll(/class="[^"]*language-card__name[^"]*"[^>]*>([^<]+)</);
  for (const m of langMatches) {
    result.languages.push(m[1].trim());
  }
}

return [{ json: result }];
